INSERT IGNORE INTO subjects(name,icon) VALUES('Matemáticas','∑'),('Lectura crítica','Aa'),('Ciencias naturales','⚗'),('Ciencias sociales','◎'),('Inglés','EN'),('Escritura y comunicación','✎');
INSERT IGNORE INTO academic_competencies(subject_id,name,description) SELECT id,'Resolución de problemas','Modela situaciones, elige estrategias y verifica resultados.' FROM subjects WHERE name='Matemáticas';
INSERT IGNORE INTO academic_competencies(subject_id,name,description) SELECT id,'Comprensión e interpretación','Identifica ideas, relaciones e inferencias en textos.' FROM subjects WHERE name='Lectura crítica';
INSERT IGNORE INTO academic_competencies(subject_id,name,description) SELECT id,'Indagación científica','Interpreta evidencias y explica fenómenos.' FROM subjects WHERE name='Ciencias naturales';
INSERT IGNORE INTO academic_competencies(subject_id,name,description) SELECT id,'Pensamiento social','Analiza procesos históricos y dinámicas sociales.' FROM subjects WHERE name='Ciencias sociales';
INSERT IGNORE INTO academic_competencies(subject_id,name,description) SELECT id,'Comunicación en inglés','Comprende vocabulario y textos de nivel escolar.' FROM subjects WHERE name='Inglés';
INSERT IGNORE INTO academic_competencies(subject_id,name,description) SELECT id,'Producción escrita','Organiza ideas con claridad y propósito.' FROM subjects WHERE name='Escritura y comunicación';
INSERT IGNORE INTO topics(competency_id,name,grade_level) SELECT c.id,'Proporcionalidad y porcentajes',g.grade FROM academic_competencies c JOIN (SELECT 5 grade UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11) g WHERE c.name='Resolución de problemas';
INSERT IGNORE INTO topics(competency_id,name,grade_level) SELECT c.id,'Idea principal e inferencias',g.grade FROM academic_competencies c JOIN (SELECT 5 grade UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11) g WHERE c.name='Comprensión e interpretación';
INSERT IGNORE INTO topics(competency_id,name,grade_level) SELECT c.id,'Evidencia y explicación de fenómenos',g.grade FROM academic_competencies c JOIN (SELECT 5 grade UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11) g WHERE c.name='Indagación científica';
INSERT IGNORE INTO questions(topic_id,grade_level,type,prompt,answer_key,explanation,difficulty) SELECT id,grade_level,'single_choice','Una tienda ofrece un descuento del 20% sobre $50.000. ¿Cuánto se paga?','B','El 20% de 50.000 es 10.000; al restarlo quedan 40.000.',2 FROM topics WHERE name='Proporcionalidad y porcentajes';
INSERT IGNORE INTO questions(topic_id,grade_level,type,prompt,answer_key,explanation,difficulty) SELECT id,grade_level,'single_choice','En un texto, la idea principal corresponde a…','B','La idea principal expresa el sentido global que sostiene los detalles del texto.',2 FROM topics WHERE name='Idea principal e inferencias';
INSERT IGNORE INTO question_options(question_id,label,body) SELECT q.id,'A','$30.000' FROM questions q WHERE q.prompt LIKE 'Una tienda ofrece%';
INSERT IGNORE INTO question_options(question_id,label,body) SELECT q.id,'B','$40.000' FROM questions q WHERE q.prompt LIKE 'Una tienda ofrece%';
INSERT IGNORE INTO question_options(question_id,label,body) SELECT q.id,'C','$45.000' FROM questions q WHERE q.prompt LIKE 'Una tienda ofrece%';
INSERT IGNORE INTO question_options(question_id,label,body) SELECT q.id,'D','$60.000' FROM questions q WHERE q.prompt LIKE 'Una tienda ofrece%';
